import axiosInstance from "@/helpers/dashboard/axiosInstance";

// Invoices are generated by the server on request and never stored.
// One order → invoice_<orderId>.pdf; several → one PDF with an invoice per page.
export default async function downloadInvoicesApi(orderIds) {
    const ids = [...new Set(orderIds)];
    try {
        const response =
            ids.length === 1
                ? await axiosInstance.get(`/order/invoice/${ids[0]}`, { responseType: "blob" })
                : await axiosInstance.post("/order/invoices", { orderIds: ids }, { responseType: "blob" });

        const filename =
            ids.length === 1
                ? `invoice_${ids[0]}.pdf`
                : `invoices_${new Date().toISOString().slice(0, 10)}_${ids.length}-orders.pdf`;

        const url = URL.createObjectURL(new Blob([response.data], { type: "application/pdf" }));
        const link = document.createElement("a");
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (error) {
        // With responseType "blob" the server's JSON error arrives as a Blob.
        const data = error?.response?.data;
        if (data instanceof Blob) {
            try {
                error.response.data = JSON.parse(await data.text());
            } catch {
                // not JSON — keep the original error
            }
        }
        throw error;
    }
}
